import{_ as t,c as a,o,ae as i}from"./chunks/framework.ixH79I-5.js";const g=JSON.parse('{"title":"v1.1.0 Changelog","description":"Changelog","frontmatter":{"title":"v1.1.0 Changelog","description":"Changelog"},"headers":[],"relativePath":"changelog/1_1_0.md","filePath":"changelog/1_1_0.md"}'),n={name:"changelog/1_1_0.md"};function l(s,e,r,d,h,u){return o(),a("div",null,e[0]||(e[0]=[i('<h1 id="v1-1-0-changelog" tabindex="-1">v1.1.0 Changelog <a class="header-anchor" href="#v1-1-0-changelog" aria-label="Permalink to &quot;v1.1.0 Changelog&quot;">​</a></h1><p>v1.1.0 Released! Including many new features, fixes and overall improvements.</p><h3 id="new-features" tabindex="-1"><strong>New Features</strong> <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;**New Features**&quot;">​</a></h3><ul><li>Better Notices - Ability to dismiss notices, and pin them to keep them on your notices feed forever! Enabled by default, can be disabled on General settings under &quot;Better Notices Page&quot;</li><li>Visual Theme Editor - Produce your own themes with the ability to customise all elements, without needing the ability to code! Simple select different elements you would like to stylise, and select the colour or font of your choice.</li></ul><h3 id="changes" tabindex="-1"><strong>Changes</strong> <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;**Changes**&quot;">​</a></h3><ul><li>Update notification on Kamar whenever we update our extension</li><li>Changelog page on the extension menu, so you can read all of these new update notes!</li><li>Better style loader</li><li>Update Star Destroyers background picture</li><li>Shrink non-period boxes on timetable</li><li>Change Justified&#39;s back to yellow - Community feedback</li></ul><h3 id="fixes" tabindex="-1"><strong>Fixes</strong> <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;**Fixes**&quot;">​</a></h3><ul><li>Fix individual theme about page issues</li><li>Private mode now hides Student Details too</li><li>Apply button now shows custom themes in use on first load</li></ul>',8)]))}const m=t(n,[["render",l]]);export{g as __pageData,m as default};
